public enum L {
    public enum Account {
        /// Signed in. With “Automatic”, the Midea account takes over when Wi-Fi does not work. {storage}
        public static func footerSignedIn(storage: String) -> String { Localizer.text("account.footerSignedIn", ["storage": storage]) }
        /// Optional. {storage}
        public static func footerSignedOut(storage: String) -> String { Localizer.text("account.footerSignedOut", ["storage": storage]) }
        /// Midea account and password removed.
        public static var removed: String { Localizer.text("account.removed") }
